import { test } from "node:test";
import assert from "node:assert/strict";
import { clamp } from "./clamp.mjs";

test("below range returns low", () => { assert.equal(clamp(-5, 0, 10), 0); });

test("above range returns high", () => { assert.equal(clamp(15, 0, 10), 10); });

test("inside range returns value", () => { assert.equal(clamp(5, 0, 10), 5); });
